def classify(text):
    t = text.lower()
    # Priority: Sports -> Sci/Tech -> Business -> World
    for kw in sports_kw:
        if re.search(r'\b' + re.escape(kw.lower()) + r'\b', t):
            return 'Sports'
    for kw in tech_kw:
        if re.search(r'\b' + re.escape(kw.lower()) + r'\b', t):
            return 'Science/Technology'
    for kw in business_kw:
        if re.search(r'\b' + re.escape(kw.lower()) + r'\b', t):
            return 'Business'
    for kw in world_kw:
        if re.search(r'\b' + re.escape(kw.lower()) + r'\b', t):
            return 'World'
    return 'World'

